import{_ as t,o,c as e,ag as i}from"./chunks/framework.D7Pdja0E.js";const c=JSON.parse('{"title":"봇 관리","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/bots.md","filePath":"04-org-admin-guide/bots.md","lastUpdated":1776160579000}'),l={name:"04-org-admin-guide/bots.md"};function r(n,a,s,d,h,u){return o(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="봇-관리" tabindex="-1">봇 관리 <a class="header-anchor" href="#봇-관리" aria-label="Permalink to &quot;봇 관리&quot;">​</a></h1><p>기관 관리자는 Workhub에서 사용할 봇을 등록하고 관리합니다.</p><h2 id="봇이란" tabindex="-1">봇이란? <a class="header-anchor" href="#봇이란" aria-label="Permalink to &quot;봇이란?&quot;">​</a></h2><p>봇은 자동화된 작업을 수행하는 프로그램입니다. 채널에 알림을 보내거나, 외부 서비스와 연동하는 데 사용합니다.</p><h2 id="봇-목록" tabindex="-1">봇 목록 <a class="header-anchor" href="#봇-목록" aria-label="Permalink to &quot;봇 목록&quot;">​</a></h2><p>관리 &gt; <strong>봇 관리</strong> 메뉴에서 등록된 봇 목록을 확인합니다.</p><h2 id="봇-등록" tabindex="-1">봇 등록 <a class="header-anchor" href="#봇-등록" aria-label="Permalink to &quot;봇 등록&quot;">​</a></h2><ol><li><strong>&quot;+ 봇 추가&quot;</strong> 버튼을 클릭합니다.</li><li>다음 정보를 입력합니다: <ul><li>봇 이름</li><li>설명</li><li>프로필 이미지 (선택)</li></ul></li><li><strong>&quot;등록&quot;</strong> 버튼을 클릭합니다.</li><li>등록 후 <strong>API 키</strong>가 발급됩니다.</li></ol><blockquote><p><strong>주의</strong>: API 키는 등록 시 한 번만 표시됩니다. 안전한 곳에 저장해 주세요.</p></blockquote><h2 id="봇-설정" tabindex="-1">봇 설정 <a class="header-anchor" href="#봇-설정" aria-label="Permalink to &quot;봇 설정&quot;">​</a></h2><h3 id="api-키-재발급" tabindex="-1">API 키 재발급 <a class="header-anchor" href="#api-키-재발급" aria-label="Permalink to &quot;API 키 재발급&quot;">​</a></h3><ol><li>봇 상세에서 <strong>&quot;키 재발급&quot;</strong> 버튼을 클릭합니다.</li><li>기존 키는 즉시 무효화되며, 새 키가 발급됩니다.</li></ol><h3 id="봇-비활성화" tabindex="-1">봇 비활성화 <a class="header-anchor" href="#봇-비활성화" aria-label="Permalink to &quot;봇 비활성화&quot;">​</a></h3><ol><li>봇 상세에서 <strong>&quot;비활성화&quot;</strong> 버튼을 클릭합니다.</li><li>비활성화된 봇은 API 호출이 차단됩니다.</li></ol><h2 id="시스템-플랫폼-봇" tabindex="-1">시스템/플랫폼 봇 <a class="header-anchor" href="#시스템-플랫폼-봇" aria-label="Permalink to &quot;시스템/플랫폼 봇&quot;">​</a></h2><p>Workhub에 기본 내장된 시스템 봇(검색 봇, 태스크 봇, 알림 봇)과 플랫폼 봇(스탠드업, 투표/설문, 취합, 태스크 알림)은 <strong>시스템 관리자만</strong> 수정/삭제/키 관리가 가능합니다.</p><p>일반 기관 관리자는 시스템/플랫폼 봇을 <strong>목록에서 확인</strong>할 수 있지만, 편집이나 삭제 버튼은 표시되지 않습니다.</p><table tabindex="0"><thead><tr><th>봇 유형</th><th>기관 관리자</th><th>시스템 관리자</th></tr></thead><tbody><tr><td>사용자 등록 봇</td><td>조회/수정/삭제 가능</td><td>모든 권한</td></tr><tr><td>시스템/플랫폼 봇</td><td>조회만 가능</td><td>모든 권한</td></tr></tbody></table><h2 id="봇-api-사용" tabindex="-1">봇 API 사용 <a class="header-anchor" href="#봇-api-사용" aria-label="Permalink to &quot;봇 API 사용&quot;">​</a></h2><p>봇은 REST API를 통해 다음 작업을 수행할 수 있습니다:</p><ul><li>채널에 메시지 전송</li><li>DM 전송</li><li>채널 목록 조회</li><li>사용자 정보 조회</li></ul><p>API 요청 시 헤더에 API 키를 포함합니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer {API_KEY}</span></span></code></pre></div>',23)])])}const b=t(l,[["render",r]]);export{c as __pageData,b as default};
